using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class RemainingPlacementRepair {
 static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static Vector3 V(JToken p)=>new Vector3((float)p[0],(float)p[1],(float)p[2]);
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform.Find("Remaining_Domes_Art");var plan=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B5_RemainingDomes/plan.json"));var used=new HashSet<Transform>();var assignments=new List<KeyValuePair<Transform,JToken>>();foreach(var p in plan["placements"]){var room=root.Find((string)p["room"]);var t=room.Find((string)p["id"]);if(!t)t=room.Cast<Transform>().FirstOrDefault(c=>!used.Contains(c)&&c.name==(string)p["model"]);if(!t||used.Contains(t))throw new Exception("Cannot uniquely resolve "+p["id"]);var path=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject);if(!path.EndsWith((string)p["model"]+".fbx"))throw new Exception("Wrong model "+p["id"]);used.Add(t);assignments.Add(new KeyValuePair<Transform,JToken>(t,p));}
 string backup=Path.Combine(Path.GetTempPath(),"AfterSeconds_Remaining_Placement_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity");if(!EditorSceneManager.SaveScene(s,backup,true))throw new Exception("Backup failed");var changed=new List<object>();foreach(var pair in assignments){var t=pair.Key;var p=pair.Value;var pos=V(p["position"]);var rot=Quaternion.Euler(0,(float)p["yaw"],0);if(t.name!=(string)p["id"]||Vector3.Distance(t.localPosition,pos)>.001f||Quaternion.Angle(t.localRotation,rot)>.01f)changed.Add(new{from=t.name,to=(string)p["id"],before=t.localPosition.ToString(),after=pos.ToString()});t.name=(string)p["id"];t.localPosition=pos;t.localRotation=rot;}
 int recorded=0;foreach(var t in root.GetComponentsInChildren<Transform>(true)){if(!PrefabUtility.IsPartOfPrefabInstance(t))continue;PrefabUtility.RecordPrefabInstancePropertyModifications(t);PrefabUtility.RecordPrefabInstancePropertyModifications(t.gameObject);foreach(var r in t.GetComponents<Renderer>())PrefabUtility.RecordPrefabInstancePropertyModifications(r);recorded++;}Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);
 foreach(string model in new[]{"RD_CentralOperatorDesk","RD_TransferNurseDesk","RD_ArchiveCaseRack","RD_WaitingBench"})AssetDatabase.ImportAsset("Assets/Afrer_Seconds/05.Model/Props/B5/"+model+".fbx",ImportAssetOptions.ForceUpdate|ImportAssetOptions.ForceSynchronousImport);EditorSceneManager.OpenScene(s.path);var validation=Validate();var result=new{backup,changed,recorded,validation};File.WriteAllText(Repo+"/Docs/검수/2026-11-08_B5_RemainingDomes/placement_repair.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
 public static object Validate(){var root=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform.Find("Remaining_Domes_Art");var plan=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B5_RemainingDomes/plan.json"));int n=0;foreach(var p in plan["placements"]){var t=root.Find((string)p["room"]+"/"+(string)p["id"]);if(!t||Vector3.Distance(t.localPosition,V(p["position"]))>.001f||Quaternion.Angle(t.localRotation,Quaternion.Euler(0,(float)p["yaw"],0))>.01f)throw new Exception("Placement mismatch "+p["id"]);n++;}return new{placements=n,matched=n,dirty=SceneManager.GetActiveScene().isDirty};}
}
